    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # The signal runs may touch either edge: preserve its contiguous segment
    # and paint the remaining background cells to its right as 1.
    marker = max((v for v in counts if v != bg), key=counts.get)
    for r, row in enumerate(grid):
        left = 0
        while left < len(row) and row[left] == marker:
            left += 1
        if 0 < left < len(row) and all(v == bg for v in row[left:]):
            for c in range(left, len(row)):
                out[r][c] = 1
            continue
        # A run ending at the right edge has its missing continuation filled
        # using 1; interior/background interruptions are left untouched.
        right = len(row)
        while right > 0 and row[right - 1] == marker:
            right -= 1
        if 0 < right < len(row) and all(v == bg for v in row[:right]):
            for c in range(right, len(row)):
                if out[r][c] == bg:
                    out[r][c] = 1
    return out

